import math

from poisson import poisson_disk


def _min_pairwise_distance_sq(points):
    """Brute-force minimum squared distance over all pairs."""
    best = float("inf")
    n = len(points)
    for i in range(n):
        xi, yi = points[i]
        for j in range(i + 1, n):
            dx = xi - points[j][0]
            dy = yi - points[j][1]
            d = dx * dx + dy * dy
            if d < best:
                best = d
    return best


def test_no_two_points_closer_than_r():
    r = 5.0
    points = poisson_disk(seed=42)
    assert len(points) >= 2
    assert _min_pairwise_distance_sq(points) >= r * r


def test_seed_3_yields_dense_sample():
    points = poisson_disk(seed=3)
    # Area heuristic for Bridson: ~0.3-0.6 points per unit disk of radius r.
    # For 100x100, r=5 that is roughly 300+ points; require >= 250.
    assert len(points) >= 250, f"only {len(points)} points"


def test_all_points_in_bounds():
    width, height = 100.0, 100.0
    for seed in range(5):
        for x, y in poisson_disk(seed=seed):
            assert 0.0 <= x < width
            assert 0.0 <= y < height


def test_deterministic_per_seed():
    for seed in (0, 3, 17):
        a = poisson_disk(seed=seed)
        b = poisson_disk(seed=seed)
        assert a == b


def test_min_distance_property_multiple_seeds():
    r = 5.0
    for seed in range(8):
        points = poisson_disk(seed=seed)
        assert _min_pairwise_distance_sq(points) >= r * r - 1e-9

